  if (request.url().includes('/product')) {
    const headers = request.headers()
    console.log('REQUEST', request.url(), headers.rsc || '', headers['next-router-prefetch'] || '', headers['next-router-segment-prefetch'] || '')
  }
})
await page.goto('http://localhost:3100/')
