import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
let releaseInventory
const inventoryGate = new Promise(resolve => { releaseInventory = resolve })
let heldRequests = 0
await page.route('**/product?*', async route => {
  const headers = route.request().headers()
  if (headers.rsc === '1' && "'!headers['"'next-router-prefetch']) {
    heldRequests += 1
    await inventoryGate
  }
  await route.continue()
})
try {
  const shellPrefetch = page.waitForResponse(response =>
    response.url().includes('/product?') &&
    response.request().headers()['next-router-segment-prefetch'] === '/product/__PAGE__'
  )
  await page.goto('http://localhost:3100/')
  await shellPrefetch
  await page.getByRole('link', { name: 'View Product' }).click()
  await page.getByRole('heading', { name: 'Premium Widget' }).waitFor({ timeout: 3000 })
  await page.getByRole('status', { name: 'Loading inventory...' }).waitFor({ timeout: 3000 })
  console.log('Title and loading status visible while inventory request is held:', heldRequests > 0)
  releaseInventory()
  await page.getByText(/\\d+ in stock/).waitFor({ timeout: 3000 })
  await page.getByText(/Price: \\"'$'"\\d+\\.\\d{2}/).waitFor({ timeout: 3000 })
  console.log('Live stock and price appeared after request release')
} finally {
  releaseInventory()
  await browser.close()
}
NODE"

