import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
page.on('request', request => {
  if (request.url().includes('/product')) {
    const headers = request.headers()
    console.log('REQUEST', request.url(), headers.rsc || '', headers['next-router-prefetch'] || '', headers['next-router-segment-prefetch'] || '')
  }
})
await page.goto('http://localhost:3100/')
await page.getByRole('link', { name: 'View Product' }).click()
await page.getByRole('heading', { name: 'Premium Widget' }).waitFor()
console.log('TITLE', await page.getByRole('heading', { name: 'Premium Widget' }).isVisible())
console.log('INVENTORY', await page.locator('text=/in stock/').textContent())
await browser.close()
